import React from "react";
import { AbsoluteFill, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS, STYLE, headlineGradient, ENGRAVE_SHADOW } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const W = 1080;
const H = 1920;
const PAD = 96;

type Dot = {
  tx: number;
  ty: number;
  sx: number;
  sy: number;
  size: number;
  color: string;
  delay: number;
  linger: boolean;
  phase: number;
  speed: number;
};

const numParam = (v: unknown, d: number): number =>
  typeof v === "number" && Number.isFinite(v) ? v : d;

const strParam = (v: unknown, d: string): string =>
  typeof v === "string" && v.trim().length > 0 ? v.trim() : d;

const clamp = (v: number, lo: number, hi: number): number => Math.max(lo, Math.min(hi, v));

// Seeded RNG so the particle field is identical across renders (same rule as the starfield).
const makeRng = (seed: number) => {
  let s = (seed || 1) >>> 0;
  return () => {
    s = (s * 1664525 + 1013904223) >>> 0;
    return s / 4294967296;
  };
};

const wrapLines = (s: string, max: number): string[] => {
  const words = s.split(/\s+/).filter(Boolean);
  const out: string[] = [];
  let cur = "";
  for (const w of words) {
    const next = cur ? cur + " " + w : w;
    if (next.length > max && cur) {
      out.push(cur);
      cur = w;
    } else {
      cur = next;
    }
  }
  if (cur) out.push(cur);
  return out.length > 0 ? out : [""];
};

const ParticleAssemble: React.FC<PrimitiveProps> = ({ anim, fps, dark }) => {
  const frame = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const params = anim.params ?? {};

  const headline = strParam(anim.text, "").toUpperCase();
  const eyebrow = strParam(params.eyebrow, "");
  const maxChars = clamp(Math.round(numParam(params.maxCharsPerLine, 14)), 6, 32);
  const count = clamp(Math.round(numParam(params.count, 150)), 24, 320);
  const spread = clamp(numParam(params.spread, 560), 120, 1400);

  const inkText = dark ? COLORS.textOnDark : COLORS.textOnLight;
  const mutedText = dark ? COLORS.mutedOnDark : COLORS.mutedOnLight;

  const lines = wrapLines(headline, maxChars);
  const longest = lines.reduce((m, l) => Math.max(m, l.length), 1);
  const fontSize = clamp((W - PAD * 2) / (longest * 0.46), 44, 168);
  const lineH = fontSize * 0.94;
  const blockH = lineH * lines.length;
  const centerY = H / 2 + (eyebrow ? 22 : 0);

  const assembleEnd = Math.max(14, Math.round(total * 0.6));
  const travel = Math.max(8, Math.min(Math.round(fps * 0.8), assembleEnd - 4));
  const maxDelay = Math.max(0, assembleEnd - travel);
  const lineCount = lines.length;
  const lineKey = lines.join("|");

  const dots = React.useMemo<Dot[]>(() => {
    const r = makeRng(count * 7919 + Math.round(fontSize) * 104729 + lineKey.length * 31);
    const src = wrapLines(headline, maxChars);
    const out: Dot[] = [];
    for (let i = 0; i < count; i++) {
      const li = Math.min(src.length - 1, Math.floor(r() * src.length));
      const chars = (src[li] || "").length || 1;
      const lw = Math.min(W - PAD * 2, Math.max(fontSize, chars * fontSize * 0.46));
      const tx = W / 2 + (r() - 0.5) * lw;
      const ty = centerY - blockH / 2 + lineH * (li + 0.5) + (r() - 0.5) * fontSize * 0.6;
      const ang = r() * Math.PI * 2;
      const rad = spread * (0.35 + 0.65 * r());
      const hue = r();
      out.push({
        tx,
        ty,
        sx: tx + Math.cos(ang) * rad,
        sy: ty + Math.sin(ang) * rad * 0.8,
        size: 1.6 + r() * 3.2,
        // one hue family only: molten gold + a few star-white dots
        color:
          hue < 0.34
            ? COLORS.tealBright
            : hue < 0.62
            ? COLORS.teal
            : hue < 0.82
            ? COLORS.gold
            : inkText,
        delay: r() * maxDelay,
        linger: r() < 0.22,
        phase: r() * Math.PI * 2,
        speed: 0.05 + r() * 0.08,
      });
    }
    return out;
  }, [count, spread, fontSize, lineH, blockH, centerY, maxDelay, lineKey, lineCount, inkText, headline, maxChars]);

  const reveal = interpolate(frame, [assembleEnd * 0.45, assembleEnd * 0.98], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.quad),
  });

  const tail = interpolate(frame, [total - 6, total - 1], [1, 0], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const headlineFill: React.CSSProperties =
    STYLE.headline === "gradient"
      ? {
          background: headlineGradient(),
          WebkitBackgroundClip: "text",
          backgroundClip: "text",
          color: "transparent",
        }
      : { color: inkText, textShadow: ENGRAVE_SHADOW };

  return (
    <AbsoluteFill style={{ opacity: tail }}>
      <AbsoluteFill
        style={{
          background: `radial-gradient(60% 34% at 50% ${(centerY / H) * 100}%, ${COLORS.teal}, transparent 68%)`,
          opacity: 0.14 * reveal,
        }}
      />

      {dots.map((d, i) => {
        const prog = interpolate(frame, [d.delay, d.delay + travel], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
          easing: Easing.out(Easing.cubic),
        });
        const appear = interpolate(frame, [d.delay, d.delay + travel * 0.3], [0, 1], {
          extrapolateLeft: "clamp",
          extrapolateRight: "clamp",
        });
        const twinkle = 0.5 + 0.5 * Math.sin(frame * d.speed + d.phase);
        const alpha = d.linger
          ? appear * (0.3 + 0.6 * twinkle)
          : appear *
            interpolate(frame, [d.delay + travel, d.delay + travel + 14], [1, 0], {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
            });
        const drift = d.linger ? Math.sin(frame * 0.035 + d.phase) * 5 : 0;
        const scale = interpolate(prog, [0, 0.82, 1], [0.55, 1.3, 1]);
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: d.sx + (d.tx - d.sx) * prog,
              top: d.sy + (d.ty - d.sy) * prog + drift,
              width: d.size,
              height: d.size,
              marginLeft: -d.size / 2,
              marginTop: -d.size / 2,
              borderRadius: STYLE.sharp ? 0 : 999,
              background: d.color,
              boxShadow: `0 0 ${d.size * 3}px ${d.color}`,
              opacity: alpha,
              transform: `scale(${scale})`,
            }}
          />
        );
      })}

      <AbsoluteFill style={{ alignItems: "center", justifyContent: "center", padding: PAD }}>
        <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 10 }}>
          {eyebrow ? (
            <div
              style={{
                fontFamily: FONTS.body,
                fontWeight: FONTS.bodyWeight,
                fontSize: 22,
                letterSpacing: "0.22em",
                textTransform: "uppercase",
                color: mutedText,
                opacity: reveal,
              }}
            >
              {eyebrow}
            </div>
          ) : null}

          <div
            style={{
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize,
              lineHeight: `${lineH}px`,
              textAlign: "center",
              textTransform: "uppercase",
              opacity: reveal,
              filter: `blur(${(1 - reveal) * 7}px)`,
              transform: `scale(${interpolate(reveal, [0, 1], [0.97, 1])})`,
              ...headlineFill,
            }}
          >
            {lines.map((l, i) => (
              <div key={i}>{l}</div>
            ))}
          </div>
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default ParticleAssemble;

import React from "react";
import {
  AbsoluteFill,
  Img,
  useCurrentFrame,
  interpolate,
  Easing,
  random,
} from "remotion";
import {
  COLORS,
  FONTS,
  STYLE,
  PANEL_SHADOW,
  ENGRAVE_SHADOW,
  headlineGradient,
} from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const num = (v: unknown, d: number): number =>
  typeof v === "number" && Number.isFinite(v) ? v : d;

const str = (v: unknown): string => (typeof v === "string" ? v.trim() : "");

// 0 -> 1 ramp, decelerating, clamped at both ends
const ease = (f: number, a: number, b: number): number =>
  interpolate(f, [a, Math.max(a + 1, b)], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
    easing: Easing.out(Easing.cubic),
  });

const ParticleImageAssemble: React.FC<PrimitiveProps> = ({ anim, fps, dark }) => {
  const frame = useCurrentFrame();
  const total = Math.max(1, Math.round((anim.end - anim.start) * fps));
  const p = (anim.params ?? {}) as Record<string, unknown>;

  const src = str(p.src) || str(p.image) || str(p.url);
  const [broken, setBroken] = React.useState(false);
  const hasImage = src !== "" && !broken;

  const count = Math.round(Math.max(24, Math.min(240, num(p.count, 150))));
  const assembleAt = Math.max(0.25, Math.min(0.9, num(p.assembleAt, 0.6)));
  const settle = Math.max(10, total * assembleAt);
  const scatter = Math.max(0.2, Math.min(2.5, num(p.scatter, 1)));

  const boxW = Math.round(Math.max(320, Math.min(920, num(p.width, 820))));
  const boxH = Math.round(
    Math.max(
      320,
      Math.min(1200, boxW * Math.max(0.5, Math.min(2, num(p.ratio, 1.2))))
    )
  );
  const radius = STYLE.sharp ? 0 : Math.max(0, num(p.radius, 26));

  // particle lattice over the image rect
  const cols = Math.max(2, Math.round(Math.sqrt((count * boxW) / boxH)));
  const rows = Math.max(2, Math.ceil(count / cols));
  const cellW = boxW / cols;
  const cellH = boxH / rows;

  const accents = [COLORS.tealBright, COLORS.teal, COLORS.gold, COLORS.leather];
  const caption = str(anim.text);
  const captionColor = dark ? COLORS.textOnDark : COLORS.textOnLight;

  const reveal = ease(frame, settle * 0.6, settle);
  const capIn = ease(frame, settle + 4, settle + 22);

  const cx = 1080 / 2;
  const cy = 1920 / 2;
  const left = cx - boxW / 2;
  const top = cy - boxH / 2;

  return (
    <AbsoluteFill style={{ width: 1080, height: 1920 }}>
      {/* accent bloom behind the plate */}
      <div
        style={{
          position: "absolute",
          left,
          top,
          width: boxW,
          height: boxH,
          borderRadius: radius,
          boxShadow: `0 0 160px ${COLORS.teal}`,
          opacity: 0.28 * reveal,
        }}
      />

      {/* the assembled user image */}
      <div
        style={{
          position: "absolute",
          left,
          top,
          width: boxW,
          height: boxH,
          borderRadius: radius,
          overflow: "hidden",
          backgroundColor: COLORS.vellum,
          boxShadow: PANEL_SHADOW,
          opacity: reveal,
          transform: `scale(${0.94 + 0.06 * reveal})`,
          filter: `blur(${(1 - reveal) * 14}px)`,
        }}
      >
        {hasImage ? (
          <Img
            src={src}
            onError={() => setBroken(true)}
            style={{
              width: "100%",
              height: "100%",
              objectFit: "cover",
              display: "block",
            }}
          />
        ) : (
          <div
            style={{
              width: "100%",
              height: "100%",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              background: `repeating-linear-gradient(45deg, ${COLORS.vellum} 0px, ${COLORS.vellum} 14px, ${COLORS.ink} 14px, ${COLORS.ink} 28px)`,
            }}
          >
            <span
              style={{
                fontFamily: FONTS.mono,
                fontSize: 22,
                letterSpacing: ".18em",
                textTransform: "uppercase",
                color: COLORS.mutedOnLight,
              }}
            >
              uploaded image
            </span>
          </div>
        )}
      </div>

      {/* particle swarm — converges onto the image lattice, then dissolves into it */}
      {Array.from({ length: count }).map((_, i) => {
        const col = i % cols;
        const row = Math.floor(i / cols);
        const tx =
          (col + 0.5) * cellW - boxW / 2 + (random("jx" + i) - 0.5) * cellW * 0.9;
        const ty =
          (row + 0.5) * cellH - boxH / 2 + (random("jy" + i) - 0.5) * cellH * 0.9;

        const ang = random("a" + i) * Math.PI * 2;
        const dist = (380 + random("d" + i) * 820) * scatter;
        const delay = random("t" + i) * settle * 0.45;

        const prog = ease(frame, delay, settle);
        const drift = 1 - prog;
        const x = tx + Math.cos(ang) * dist * drift;
        const y = ty + Math.sin(ang) * dist * 1.1 * drift;

        const base = 2 + random("s" + i) * 4.5;
        const size = base * (1 + drift * 0.6);
        const color = accents[Math.floor(random("c" + i) * accents.length) % accents.length];
        const twinkle =
          0.6 + 0.4 * Math.sin((frame + i * 9) / (5 + random("w" + i) * 9));
        const appear = ease(frame, delay, delay + 6);
        const opacity = Math.max(0, appear * twinkle * (1 - reveal * 0.88));

        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: cx + x - size / 2,
              top: cy + y - size / 2,
              width: size,
              height: size,
              borderRadius: "50%",
              backgroundColor: color,
              boxShadow: `0 0 ${size * 3}px ${color}`,
              opacity,
            }}
          />
        );
      })}

      {caption === "" ? null : (
        <div
          style={{
            position: "absolute",
            left: 0,
            top: cy + boxH / 2 + 46,
            width: "100%",
            textAlign: "center",
            padding: "0 48px",
            boxSizing: "border-box",
            opacity: capIn,
            transform: `translateY(${(1 - capIn) * 18}px)`,
          }}
        >
          <span
            style={{
              display: "inline-block",
              fontFamily: FONTS.display,
              fontWeight: FONTS.displayWeight,
              fontSize: 62,
              lineHeight: 0.95,
              textTransform: "uppercase",
              letterSpacing: ".01em",
              ...(STYLE.headline === "gradient"
                ? {
                    backgroundImage: headlineGradient(),
                    WebkitBackgroundClip: "text",
                    backgroundClip: "text",
                    color: "transparent",
                  }
                : { color: captionColor, textShadow: ENGRAVE_SHADOW }),
            }}
          >
            {caption}
          </span>
        </div>
      )}
    </AbsoluteFill>
  );
};

export default ParticleImageAssemble;
